internal sealed class ActualMobiusCovarianceDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original actual-field special-conformal Ward law: proof in progress",
        H("Actual Mobius L1 covariance"), Blocks(
        Describe.Lean(DescribeId.Create("actual-mobius-charged-l1-base"),
            DeclarationHandle.Create("D5/S3/VertexAlgebra/HalfFock/ActualMobiusCovariance.charged_l1_coefficient"),
            H("Charged special-conformal coefficient base"), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(LibraryNoteRef.Create("D5/L/VertexAlgebra/flm1988monster")),
            Blocks(Paragraph(Text("For every original D, determinant-unit proof hu, signed charge a and integer e, the commutator of tensorL at mode 1 with chargedCoefficient at e equals ((e-2)/2+B(a,a)) times chargedCoefficient at e-2, as an endomorphism of the original actual tensor module. The proof expands the pointwise finite quadratic sum, retains the j=0 boundary, contracts both inverse Gram identities and consumes the original physical seed identity. This charged calculation is a dependency of the intended full-source proof, not its completion; no positivity, rank restriction or homogeneous target is assumed. Kernel status and independent review are recorded separately from this narrative."))), DescribeRole.Theorem),
        Paragraph(Text("The retained objective is the original all-source physical coefficient law with z=t^2. For every D:LatticeData, hu:IsUnit D.G.det, a:Carrier D and e:Int, put A_e(a)=(correctedField D hu a).coeff e, T1=tensorL D (ActualGround D hu) (actualInverse D) 1 and Sj=sugawaraMode D (gramComplex D)^(-1) j. The target is T1*A_e(a)-A_e(a)*T1=A_e(S1 a)+(e/2-1) A_(e-2)(a)+2 A_(e-2)(S0 a). It is an equality on the original actual tensor module, with every target input, signed charge and exponent, rank zero and indefinite symmetric even unimodular Gram forms in scope. The target is not yet established by this WIP source.")),
        Paragraph(Text("The charged proof route expands tensor_rawL_finsum at mode 1, where the pair indices are j and -j. The charged current Ward identity produces the original singleton at exponent e-4 and its reindexing under j to -j. At j=0 the reversed normal ordering leaves the product of the two original charge pairings times C_(e-2). The inverse Gram contractions must retain the resulting Q/2 term. The existing charged_seed_physical_coefficient then supplies the required coefficient (e-2)/2+Q. All infinite-looking sums are pointwise finite after application at x or C_e x; no finite support in Module.End is assumed.")),
        Paragraph(Text("The local singleton commutator is proved pointwise on every original actual target input. Write N_(i,r)(F)=singletonLinear (i,r) F. Given the shorter-source induction data [T1,F_d]=G_d+(d/2-1)F_(d-2)+2H_(d-2), its conclusion is [T1,N_(i,r)(F)_e]=N_(i,r)(G)_e+(e/2-1+2(r+1))N_(i,r)(F)_(e-2)+2N_(i,r)(H)_(e-2), plus zero for r=0 or (r+1)N_(i,r-1)(F)_e otherwise, plus (1/2)halfBinomial(r)[tensorCurrent_i(0),F_(e+2r+1)]. The single-term proof isolates j=-1 to 0. The summed proof uses finite support only after application at x or T1(x), reindexes j to j+1, and applies the original jet Pascal/product-rule scalar. This local induction lemma does not assume or establish the final all-source law as an external premise.")),
        Paragraph(Text("The remaining source step uses correctedField_negative_current_insertion, one singleton normal-order L1 commutator with the -1 to 0 crossover, the universal half-binomial scalar cancellation, and strong oscillator-length induction. For the original insertion scalar k(m,n)=m hb(m) hb(n)/(m+n), the cancellation is (1/2)hb(m-1)choose(1/2,n)=(m+n)k(m,n)+prev(m,n)+(if m>1 then m k(m-1,n) else delta(n,0)), with prev=0 at n=0 and (n-1)k(m,n-1) otherwise. Ordinary Corr commutation with source L1 while fixing the shift symbol is not used. The independent source L0 and L1 terms must both remain in the conclusion.")),
        Paragraph(Text("The classical background is Frenkel, Lepowsky and Meurman, Vertex Operator Algebras and the Monster; Dong and Nagatomo, math/9808088v1; and Bakalov and Kac, math/0402315v1. Imported current and tensor implementations retain their Kalle Kytola and other original attributions. No literature novelty, independent review, Pro participation or full covariance proof is claimed by this checkpoint. Translation, energy covariance, finite conjugation, inversion and analytic/global geometry have their own proof obligations. The full Monster, VOA, CFT, anomalies, fusion, string theory and AdS/CFT objective remains incomplete.")))));
}
